import{_ as o,l as E,o as e,c as i,v as r,p as l,x as t,d as s,i as B,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"跨期套利","description":"","frontmatter":{"title":"跨期套利","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/calendar-spread-arb.md","filePath":"quant/calendar-spread-arb.md","lastUpdated":1789023840000}'),p={name:"quant/calendar-spread-arb.md"};function h(A,a,m,u,c,_){const n=E("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="跨期套利" tabindex="-1">跨期套利 <a class="header-anchor" href="#跨期套利" aria-label="Permalink to &quot;跨期套利&quot;">​</a></h1><div class="epigraph"><p>不同到期期货之间的价差，是仓储与便利收益在时间上的差分；把它当成两张高度相关合约的统计回归，会在交割月与库存冲击里把「均值」写丢。</p><footer>—— Working 的持有费与反持有费；价差波动见 Ng &amp; Pirrong 对金属库存与波动的讨论</footer></div><p>跨期套利（calendar spread）交易同一商品、不同到期的期货：买远月卖近月，或反向，有时再加一个更远的合约做成蝶式。它看起来像期现套利抽掉现货腿，只用期货曲线的一阶差分。Working 把近月相对远月的持有费写成库存状态；库存充裕时价差接近全额仓储加融资，库存紧张时价差可以变成贴水且波动上升。Ng 与 Pirrong（1994）对金属表明，库存低时现货与近月波动更高、价差更不稳定。Hull 的持有成本给出价差的无套利参照，但不保证价差在交割选择权、挤仓与指数滚仓下沿着参照走。统计套利常用的 OU 半衰期在这里是危险的隐喻：价差的「均值」会随库存报告、季节与仓单注销而跳。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记近月价格 \\(F_{t,T_1}\\)、远月 \\(F_{t,T_2}\\)。在持有成本世界里，</p> \\[F_{t,T_2}-F_{t,T_1}\\approx S_t\\mathrm{e}^{(r+u-y)(T_2-t)}-S_t\\mathrm{e}^{(r+u-y)(T_1-t)}, \\]<p>价差主要由 \\(r+u-y\\) 与间隔决定。\\(y\\) 随库存变，价差就随库存变。问题是：交易者看到的日历价差报价，混入了交割选择权（品质、地点、时间）、近月流动性溢价、以及指数在特定窗口卖掉 \\(T_1\\)、买进 \\(T_2\\) 的需求。把价差相对过去 60 日均值的偏离当成误定价，等于假设 \\(y\\) 在 60 日内不变。农产品收获、能源取暖季、金属罢工，都会让这个假设在你持仓正大时失败。</p><p>第二层问题是腿的可替代性。近月进入交割或持仓限制之后，你卖出的那条腿可能无法按远月的逻辑平仓，价差从「仓储差分」变成「挤仓期权」。Gay 与 Manaster 讨论期货里的品质选择权；商品日历价差同样内嵌近月是否被交割、被挤的期权。第三层是保证金：交易所对日历价差收较低保证金，杠杆高于单边，资金把小基点利润放大的同时，也把交割月缺口放大。</p><h3 id="价差不是期现的影子复制" tabindex="-1">价差不是期现的影子复制 <a class="header-anchor" href="#价差不是期现的影子复制" aria-label="Permalink to &quot;价差不是期现的影子复制&quot;">​</a></h3><p><a href="/quant/cash-and-carry">期现套利</a> 有一张现货存货和一张期货；跨期是两张期货，没有仓单现金流，除非你主动接货再抛到更远的合约。因此跨期赚的是曲线形状变化，不是仓储费本身。正向市场里买远卖近，若升水收窄（库存被消化、\\(y\\) 上升），价差交易亏损，即便现货没动。这与<a href="/quant/roll-yield">展期收益</a>的会计相反：被动多头在升水里付展期；主动买远卖近是在赌升水扩大或维持。两者可以同时存在于同一个市场，盈亏符号相反。</p><p><span class="marginnote">指数滚仓周，公开规则把大量仓位从 \\(T_1\\) 迁到 \\(T_2\\)，日历价差会被打向「对指数友好」的方向。把这一窗口的均值回归当成仓储套利，你是在提供流动性给指数，见 Mou 与 Bessembinder 等对可预测滚仓的研究。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先把价差定义成可交易合约与固定乘数（有的市场近月与远月合约规模不同，或有裂解价差）。用仓储加融资的上界做参照带，用库存分位与季节做状态，而不是用无条件均值。开仓仅当价差超出带且库存状态与之矛盾——例如高库存却出现深度贴水，需要排除挤仓与交割地局部短缺之后，才更像可交易的错价。蝶式限制曲线的二阶弯曲，对平行的 \\(r\\) 更不敏感，但对中间合约的流动性更敏感。</p><p>执行必须处理腿的不同深度：近月通常更厚，远月更薄，同时成交会在远月留下冲击，价差在成交完成前已经移动。部分成交使日历价差变成带 delta 的方向性仓位。容量取两腿深度的较小者，再打折，因为价差交易者与展期者、对冲者挤在同一本上。风险限额应按交割月临近逐步强制减仓，而不是按价差 z-score 加仓。</p><h3 id="金属、能源与农产品不是同一套价差" tabindex="-1">金属、能源与农产品不是同一套价差 <a class="header-anchor" href="#金属、能源与农产品不是同一套价差" aria-label="Permalink to &quot;金属、能源与农产品不是同一套价差&quot;">​</a></h3><p>Ng–Pirrong 的金属证据强调库存对波动与价差的非线性。能源有管道与库存报告的周频跳跃，价差在 EIA 公布前后的条件分布与平日不同，见<a href="/quant/inventory-curve">库存报告与曲线</a>。农产品有明确的新旧作切换，旧作近月与新作远月之间的价差可以包含作物失败期权，均值在生长季节不是常数。把三个板块的日历价差放进同一个 PCA 因子，载荷在收获周会断裂。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>仓储机制：库存上升，持有费上升，买远卖近获利（升水扩大）；库存下降，便利收益上升，反向价差获利。这是 Working 反持有费（inverse carrying charge）的交易版。波动机制：低库存时近月对信息更敏感，价差方差变大，同样的保证金杠杆对应更大的爆仓概率。Ng–Pirrong 把基本面、库存与价格波动写在一起，就是在说价差的风险不是常数。</p><p>交割机制：临近 \\(T_1\\)，空头近月面临交割匹配、持仓限制与可能的挤仓。价差里的近月空头不是无风险的「短端融资」，而是一个有交割期权的空头。多头近月则可能被迫接货。日历价差在进入交割月之后，性质从相对价值变成或有实物。指数滚仓机制把部分价差变动从仓储改写成订单流，详见<a href="/quant/roll-volume-oi">展期成交量与持仓</a>。</p><h3 id="破裂-挤仓、限仓、月份切换" tabindex="-1">破裂：挤仓、限仓、月份切换 <a class="header-anchor" href="#破裂-挤仓、限仓、月份切换" aria-label="Permalink to &quot;破裂：挤仓、限仓、月份切换&quot;">​</a></h3><p>挤仓时近月脱离仓储曲线，卖近买远的「便宜升水」可以无限变贵。交易所提高保证金或强制减仓时，价差仓位的杠杆优势消失，你必须在最差的流动性里平一侧。合约到期切换使连续价差序列出现跳点：回测若用未经调整的拼接，会出现虚假的均值回归。监管调查、注册仓单突击注销、港口罢工，都是状态变量的间断，OU 拟合会把间断前的均值当成间断后的锚。</p><p><span class="marginnote">低保证金的日历价差在风险系统里常被当成「几乎对冲」。正确的风险是曲线一阶（仓储）与近月特异性（挤仓）。用单边名义的很小比例去设止损，会在近月跳空时直接穿。应按近月独立冲击加价差冲击两条限额。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把跨期写成无现货的期现：没有入库权，你就不能收取教科书仓储。不要在交割月用历史分位开新仓。不要忽略裂解、跨商品价差与日历价差的区别——汽油–原油是炼厂边际，不是同一仓储曲线的差分。成本含两腿价差、远月冲击、以及滚仓周与你同向的拥挤。容量随交割临近下降，不是随未平仓量上升。</p><p>与国债<a href="/quant/implied-repo">隐含回购</a>和 CTD 的对照：利率期货的日历价差还受最便宜可交割券切换影响，商品则受仓单与库存影响。两者都是「曲线交易」，破裂来源不同。报告应分列：仓储参照偏离、库存条件、是否处于指数滚仓窗口、近月是否可交割。若这四项里有两项已经对你不利，z-score 再高也不是套利。</p><p><span class="marginnote">Working（1948）讨论的反持有费是现货相对远期可以持续升水。跨期交易者若在贴水扩大时按「总会回到正持有费」加仓，是在做空便利收益与挤仓期权。样本内的回归来自库存回补，样本外库存可以不回补。</span></p>',26)),(e(),l(d,null,{default:t(()=>[B(n,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E5%BA%93%E5%AD%98%E4%B8%8E%E5%AD%A3%E8%8A%82%22%5D%20--%3E%20Y%5B%22%E4%BE%BF%E5%88%A9%E6%94%B6%E7%9B%8A%20%2F%20%E6%8C%81%E6%9C%89%E8%B4%B9%22%5D%0A%20%20Y%20--%3E%20SPR%5B%22%E6%97%A5%E5%8E%86%E4%BB%B7%E5%B7%AE%20F(T2)-F(T1)%22%5D%0A%20%20IDX%5B%22%E6%8C%87%E6%95%B0%E6%BB%9A%E4%BB%93%E8%AE%A2%E5%8D%95%22%5D%20--%3E%20SPR%0A%20%20OPT%5B%22%E8%BF%91%E6%9C%88%E4%BA%A4%E5%89%B2%E4%B8%8E%E6%8C%A4%E4%BB%93%E6%9C%9F%E6%9D%83%22%5D%20--%3E%20SPR%0A%20%20SPR%20--%3E%20BAND%5B%22%E4%BB%93%E5%82%A8%E4%B8%8A%E7%95%8C%20%2B%20%E7%8A%B6%E6%80%81%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20BAND%20--%3E%7C%22%E5%B8%A6%E5%A4%96%E4%B8%94%E9%9D%9E%E4%BA%A4%E5%89%B2%E6%9C%88%22%7C%20TRADE%5B%22%E4%B9%B0%E8%BF%9C%E5%8D%96%E8%BF%91%E6%88%96%E5%8F%8D%E5%90%91%22%5D%0A%20%20TRADE%20--%3E%20EXE%5B%22%E8%BF%9C%E6%9C%88%E5%86%B2%E5%87%BB%E4%B8%8E%E9%83%A8%E5%88%86%E6%88%90%E4%BA%A4%22%5D%0A%20%20OPT%20--%3E%7C%22%E8%BF%9B%E5%85%A5%E4%BA%A4%E5%89%B2%20%2F%20%E6%8C%A4%E4%BB%93%22%7C%20BRK%5B%22%E4%BB%B7%E5%B7%AE%E4%B8%8E%E4%BB%93%E5%82%A8%E8%84%B1%E9%92%A9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨期套利交易同一商品不同到期的期货价差，经济对象是仓储与便利收益的时间差分，不是无条件均值回归。</li><li>Working 给出持有费与反持有费；Ng–Pirrong 表明低库存时价差更不稳、近月波动更高。</li><li>指数滚仓、交割选择权与低保证金杠杆会把仓储价差改写成订单流与挤仓期权。</li><li>容量受远月深度与交割临近约束；破裂是挤仓、限仓与月份拼接跳点。</li><li>出处：Working, <em>Journal of Farm Economics</em>, 1948 与 <em>AER</em>, 1949；Ng and Pirrong, <em>Journal of Business</em>, 1994；Gay and Manaster, <em>JFE</em>, 1984；Mou, Goldman Roll working paper；Bessembinder, Carrion, Tuttle and Venkataraman, <em>JFE</em>, 2016；Hull, <em>Options, Futures, and Other Derivatives</em>。</li></ul>',2))])}const g=o(p,[["render",h]]);export{f as __pageData,g as default};
